import { cookies, headers } from 'next/headers'

function getPreferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) return 'unknown'
  const [primary] = acceptLanguage.split(',')
  const [language] = primary.trim().split(';')
  return language.trim() || 'unknown'
}

export default async function Home() {
  const cookieStore = await cookies()
  const headersList = await headers()

  const theme = cookieStore.get('theme')?.value ?? 'light'
  const preferredLanguage = getPreferredLanguage(headersList.get('accept-language'))

  return (
    <main>
      <h1>User Preferences</h1>
      <p>Theme: {theme}</p>
      <p>Preferred language: {preferredLanguage}</p>
    </main>
  )
}
